['b4_estaq','b4_searchBox','b4_northBtn','b4_toolTab','b4_toolScrim','b4_tools','b4_toast'].forEach(id=>{const el=$(id);if(el){L.DomEvent.disableClickPropagation(el);L.DomEvent.disableScrollPropagation(el)}});
