  for(let k=i0;k<=i1;k++){if(Data.splitName(R[k][0])[1]%100)continue;const xx=x(ODO[k]);if(xx<20||xx>W-20)continue;g.beginPath();g.moveTo(xx,top-4);g.lineTo(xx,yb);g.stroke();g.fillText(R[k][0],xx,yb+2)}
