      txt('RELATÓRIO GERENCIAL DA OBRA',W/2,M+3,{z:15,b:true,a:'center'});txt(`${OBRA} · ${RODOVIA} · emitido em ${emitido}`,W/2,M+8.5,{z:8,c:MUT,a:'center'});
